// ─── File: OptionsDemo.java ───
// Single runnable file with multiple top-level package-private classes.
package com.bank.hiddenopt;

import java.lang.invoke.MethodHandles;
import java.lang.invoke.MethodHandles.Lookup.ClassOption;
import java.math.BigDecimal;
import java.util.logging.*;

public class OptionsDemo {
    private static final Logger log = Logger.getLogger(OptionsDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Throwable {
        RuleEngine engine = new RuleEngine(new BigDecimal("0.001")); // private fee rate 0.1%

        // WEAK (default): per-request validator — eligible to unload after use.
        Class<?> weakValidator = engine.defineWeakValidator();
        log.info(() -> "WEAK validator hidden=" + weakValidator.isHidden()
                + " (will unload when unreachable)");

        // STRONG: cached interest calculator — lives as long as the loader.
        Class<?> strongCalc = engine.defineStrongCalculator();
        log.info(() -> "STRONG calculator hidden=" + strongCalc.isHidden()
                + " (kept alive with its loader)");

        // NESTMATE access: the hidden class read the host's PRIVATE fee rate.
        BigDecimal feeUsingPrivate = engine.computeFeeViaHidden(new BigDecimal("1000000"));
        log.info(() -> "Fee computed by NESTMATE hidden class using host private rate = Rs."
                + feeUsingPrivate);
    }
}

// ─── Would be in engine/RuleEngine.java ───
class RuleEngine {
    private static final Logger log = Logger.getLogger(RuleEngine.class.getName());

    // PRIVATE host state that a NESTMATE hidden class is allowed to read.
    private final BigDecimal feeRate;

    RuleEngine(BigDecimal feeRate) { this.feeRate = feeRate; }

    // Package-private accessor the hidden nestmate calls to reach private rate.
    BigDecimal feeRate() { return feeRate; }

    Class<?> defineWeakValidator() throws Throwable {
        byte[] bytes = BytecodeFactory.validatorBytes();
        MethodHandles.Lookup lookup = MethodHandles.lookup();
        // NO STRONG option → default WEAK lifecycle → eligible for independent unload.
        return lookup.defineHiddenClass(bytes, true, ClassOption.NESTMATE).lookupClass();
    }

    Class<?> defineStrongCalculator() throws Throwable {
        byte[] bytes = BytecodeFactory.calculatorBytes();
        MethodHandles.Lookup lookup = MethodHandles.lookup();
        // STRONG → tied to loader lifetime, NOT independently unloaded.
        return lookup.defineHiddenClass(bytes, true,
                ClassOption.STRONG, ClassOption.NESTMATE).lookupClass();
    }

    // Demonstrates NESTMATE: the hidden FeeRule reads this.feeRate (host private).
    BigDecimal computeFeeViaHidden(BigDecimal amount) throws Throwable {
        byte[] bytes = BytecodeFactory.calculatorBytes();
        MethodHandles.Lookup lookup = MethodHandles.lookup();
        Class<?> hidden = lookup.defineHiddenClass(bytes, true, ClassOption.NESTMATE).lookupClass();
        FeeRule rule = (FeeRule) hidden.getConstructor(RuleEngine.class).newInstance(this);
        return rule.calculate(amount);
    }
}

// ─── Visible interface implemented by the hidden calculator ───
interface FeeRule { BigDecimal calculate(BigDecimal amount); }

// ─── The payload whose bytes are used as hidden classes ───
// As a NESTMATE it can call engine.feeRate() to read the host's private rate.
class CalculatorImpl implements FeeRule {
    private final RuleEngine engine;
    CalculatorImpl(RuleEngine engine) { this.engine = engine; }
    @Override public BigDecimal calculate(BigDecimal amount) {
        return amount.multiply(engine.feeRate())
                     .setScale(2, java.math.RoundingMode.HALF_UP);
    }
}

// ─── Supplies bytecode payloads (reads bundled compiled classes for clarity) ───
class BytecodeFactory {
    static byte[] validatorBytes() throws Exception { return read("com/bank/hiddenopt/CalculatorImpl.class"); }
    static byte[] calculatorBytes() throws Exception { return read("com/bank/hiddenopt/CalculatorImpl.class"); }
    private static byte[] read(String res) throws Exception {
        try (var in = BytecodeFactory.class.getClassLoader().getResourceAsStream(res)) {
            if (in == null) throw new IllegalStateException("missing: " + res);
            return in.readAllBytes();
        }
    }
}

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override public String format(java.util.logging.LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
